/**
 * Debtor data extracted from import file
 */
export interface DebtorData {
  /** Unique handle/key (string) generated by api-debts for this debtor */
  debtorId: string;

  /** Real Debt entity IDs associated with this debtor */
  debtIds: string[];

  /** First name */
  firstName?: string;

  /** Last name */
  lastName?: string;

  /** Middle name */
  middleName?: string;

  /** Date of Birth (ISO 8601 string: YYYY-MM-DD) */
  dateOfBirth?: string;

  /** Social Security Number (unhashed) */
  ssn?: string;

  /** Email address */
  email?: string;

  /** Phone number */
  phone?: string;

  /** Address line 1 */
  addressLine1?: string;

  /** Address line 2 */
  addressLine2?: string;

  /** City */
  city?: string;

  /** State */
  state?: string;

  /** ZIP code */
  zipCode?: string;
}

/**
 * Payload for PortfolioDebtorBatchReady event
 *
 * Published by api-debts during portfolio import to send batches of debtor data
 * to api-debtors for processing. Each batch contains a subset of debtors from the
 * import file to enable scalable, parallel processing.
 */
export interface PortfolioDebtorBatchReadyPayload {
  /** Import job identifier from api-debts */
  importJobId: string;

  /** Portfolio being imported */
  portfolioId: string;

  /** Organization importing the portfolio */
  organizationId: string;

  /** Batch number (1-indexed) */
  batchNumber: number;

  /** Total number of batches for this import */
  totalBatches: number;

  /** Number of debtors in this batch */
  debtorCount: number;

  /** Array of debtor data for this batch */
  debtors: DebtorData[];

  /** Timestamp when batch was published */
  publishedAt: string;
}
